class TokenStore:
    def __init__(self, timeout=3600):
        self.timeout = timeout
        self._tokens = {}

    def create(self, user_id):
        token = secrets.token_hex(32)
        self._tokens[token] = {'user_id': user_id, 'created_at': time.time()}
